begin;
set local role service_role;
do $test$
declare administrator uuid;admin_person uuid;unlinked uuid;orphan uuid:=gen_random_uuid();minor_cid uuid:=gen_random_uuid();owner_id uuid;outsider uuid;person uuid:=gen_random_uuid();other_person uuid:=gen_random_uuid();cid uuid:=gen_random_uuid();foreign_cid uuid:=gen_random_uuid();r jsonb;payload jsonb;req uuid:=gen_random_uuid();kind text;ink jsonb:='[[[0.1,0.5],[0.2,0.3],[0.3,0.6],[0.4,0.2],[0.5,0.5]]]';v bigint:=0;snapshot jsonb;
begin
 select user_id into administrator from public.social_admins where role='admin' and is_active and not is_blocked and first_name<>'' and last_name<>'' limit 1;
 select person_id into admin_person from public.social_admins where user_id=administrator;
 select user_id into unlinked from public.social_admins where person_id is null and role<>'admin' and is_active and not is_blocked and not 'trainer_contracts'=any(access_areas) limit 1;
 select user_id into owner_id from public.social_admins where role<>'admin' and is_active and not is_blocked and not 'trainer_contracts'=any(access_areas) limit 1;
 select user_id into outsider from public.social_admins where role<>'admin' and user_id<>owner_id and is_active and not is_blocked and not 'trainer_contracts'=any(access_areas) limit 1;
 if administrator is null or owner_id is null or outsider is null then raise exception 'Actors missing';end if;
 insert into public.social_people(id,slug,display_name) values(person,'portal-test-'||person,'Portal Test Coach'),(other_person,'portal-other-'||other_person,'Portal Other Coach');
 update public.social_admins set person_id=person where user_id=owner_id;
 snapshot:=jsonb_build_object('templateVersion','2026-11-03.1','name','Portal Test Coach','teamName','C-Jugend Test','season','2024/2025','start','2024-07-01','end','2025-06-30','paidMonths','[7,9,10,11,1,2,3,4,5,6]'::jsonb,'monthlyCents',10000,'birthDate','1990-01-01');
 insert into private.trainer_contracts(id,season,person_id,slot,status,snapshot,document_path,document_hash) values(cid,'2024/2025',person,'trainer','issued',snapshot,cid||'/issued/test.pdf',repeat('a',64)),(foreign_cid,'2024/2025',other_person,'trainer','issued',snapshot,foreign_cid||'/issued/test.pdf',repeat('b',64));
 insert into private.trainer_contracts(id,season,person_id,slot,status,snapshot,document_path,document_hash) values(orphan,'2024/2025',null,'trainer','issued',snapshot,orphan||'/issued/test.pdf',repeat('a',64));
 if unlinked is null then raise exception 'Unlinked actor fixture missing';end if;
 r:=public.trainer_contract_portal_request(unlinked,jsonb_build_object('action','get','id',orphan));if r->>'status'<>'403' then raise exception 'Null owner admitted an unlinked actor';end if;
 r:=public.trainer_contract_portal_request(unlinked,jsonb_build_object('action','file','id',orphan,'kind','base'));if r->>'status'<>'403' then raise exception 'Null owner file leaked';end if;
 r:=public.trainer_contract_portal_request(owner_id,'{"action":"list"}');if jsonb_array_length(r->'contracts')<>1 or r#>>'{contracts,0,id}'<>cid::text then raise exception 'Own contract listing leaks other people';end if;
 r:=public.trainer_contract_portal_request(outsider,jsonb_build_object('action','get','id',cid));if r->>'status'<>'403' then raise exception 'Unrelated person read contract';end if;
 payload:=jsonb_build_object('action','sign','id',cid,'version',0,'documentHash',repeat('a',64),'part','agreement','requestId',req,'confirmed',true,'place','Radolfzell','strokes',ink,'values','{}'::jsonb);
 r:=public.trainer_contract_portal_request(administrator,payload);if r->>'status'<>'403' then raise exception 'Admin signed for trainer';end if;
 r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'portalVersion'<>'1' or jsonb_array_length(r->'signatures')<>1 then raise exception 'Own signature failed: %',r;end if;
 r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'portalVersion'<>'1' then raise exception 'Lost-response retry duplicated signature';end if;
 r:=public.trainer_contract_portal_request(owner_id,payload||jsonb_build_object('place','Different location'));if r->>'status'<>'409' then raise exception 'Changed retry was reported as successful';end if;
 payload:=payload||jsonb_build_object('part','allowance','requestId',gen_random_uuid());r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'status'<>'409' then raise exception 'Stale version accepted';end if;
 payload:=payload||jsonb_build_object('version',1);r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'status'<>'400' then raise exception 'Blank annual declaration accepted';end if;
 payload:=payload||jsonb_build_object('values',jsonb_build_object('2024',0,'2025',0));r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'portalVersion'<>'2' then raise exception 'Annual declaration failed: %',r;end if;
 payload:=payload||jsonb_build_object('version',2,'part','conduct','requestId',gen_random_uuid(),'values','{}'::jsonb);r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'portalVersion'<>'3' then raise exception 'Code signature failed: %',r;end if;
 update public.social_admins set extra_access_areas=array_append(extra_access_areas,'trainer_contracts') where user_id=owner_id;
 payload:=payload||jsonb_build_object('version',3,'part','club','requestId',gen_random_uuid());r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'status'<>'409' then raise exception 'Self-counter-signature accepted';end if;
 update public.social_admins set person_id=other_person where user_id=owner_id;update public.social_admins set person_id=person where user_id=administrator;
 r:=public.trainer_contract_portal_request(administrator,payload);if r->>'status'<>'409' then raise exception 'Same person countersigned through another identity';end if;
 update public.social_admins set person_id=admin_person where user_id=administrator;update public.social_admins set person_id=person where user_id=owner_id;
 r:=public.trainer_contract_portal_request(administrator,payload);if r->>'portalVersion'<>'4' then raise exception 'Club signature failed: %',r;end if;
 update public.social_admins set extra_access_areas=array_remove(extra_access_areas,'trainer_contracts') where user_id=owner_id;
 r:=public.trainer_contract_portal_request(owner_id,jsonb_build_object('action','seal','id',cid,'version',4,'path',cid||'/signed/test.pdf','hash',repeat('a',64)));if r->>'status'<>'403' then raise exception 'Owner finalized as admin without independent role';end if;
 r:=public.trainer_contract_portal_request(administrator,jsonb_build_object('action','seal','id',cid,'version',4,'path',cid||'/signed/test.pdf','hash',repeat('a',64)));if r->>'status'<>'signed' then raise exception 'Complete contract not sealed: %',r;end if;
 foreach kind in array array['november','maerz','juni'] loop
  v:=v+1;payload:=jsonb_build_object('action','sign','id',cid,'version',v+3,'documentHash',repeat('a',64),'part','waiver_'||kind,'requestId',gen_random_uuid(),'confirmed',true,'place','Radolfzell','strokes',ink,'values',jsonb_build_object('amount',case when kind='november' then 40000 else 30000 end,'due',case kind when 'november' then private.trainer_contract_due(2024,11) when 'maerz' then private.trainer_contract_due(2025,3) else private.trainer_contract_due(2025,6) end,'choice',case kind when 'november' then 'donate' when 'maerz' then 'payout' else 'partial' end,'payoutCents',case kind when 'november' then 0 when 'maerz' then 30000 else 10000 end,'waivedCents',case kind when 'november' then 40000 when 'maerz' then 0 else 20000 end));
  r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'portalVersion'<>(v+4)::text then raise exception 'Declaration % failed: %',kind,r;end if;
 end loop;
 r:=public.trainer_contract_portal_request(owner_id,jsonb_build_object('action','file','id',cid,'kind','base'));if r->>'hash'<>repeat('a',64) then raise exception 'Owned file lookup failed';end if;
 if (select count(*) from private.trainer_contract_signatures where contract_id=cid)<>7 then raise exception 'Missing signature events';end if;
 if exists(select 1 from private.trainer_contract_signatures where contract_id=cid and (evidence_hash !~ '^[a-f0-9]{64}$' or document_hash<>repeat('a',64))) then raise exception 'Evidence unbound';end if;
 insert into private.trainer_contracts(id,season,person_id,slot,status,snapshot,document_path,document_hash,signed_path,signed_hash,guardian_path,guardian_hash) values(minor_cid,'2024/2025',person,'co1','signed',snapshot||jsonb_build_object('birthDate','2010-01-01','guardianName','Actual Guardian'),minor_cid||'/issued/test.pdf',repeat('a',64),minor_cid||'/signed/test.pdf',repeat('b',64),minor_cid||'/guardian/general.pdf',repeat('c',64));
 payload:=jsonb_build_object('action','sign','id',minor_cid,'version',0,'documentHash',repeat('a',64),'part','waiver_juni','requestId',gen_random_uuid(),'confirmed',true,'place','Radolfzell','strokes',ink,'values',jsonb_build_object('amount',30000,'due',private.trainer_contract_due(2025,6),'choice','donate','payoutCents',0,'waivedCents',30000));
 r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'status'<>'409' then raise exception 'General guardian consent authorized a later gift';end if;
 r:=public.trainer_contract_portal_request(administrator,jsonb_build_object('action','guardian_waiver','id',minor_cid,'version',0,'part','waiver_juni','maxWaiverCents',10000,'confirmed',true,'path',minor_cid||'/guardian/juni.pdf','hash',repeat('d',64)));if r->>'portalVersion'<>'1' then raise exception 'Specific guardian consent failed: %',r;end if;
 r:=public.trainer_contract_portal_request(owner_id,payload||jsonb_build_object('version',1));if r->>'status'<>'409' then raise exception 'Minor exceeded specifically authorized gift';end if;
 payload:=payload||jsonb_build_object('version',1,'values',jsonb_build_object('amount',30000,'due',private.trainer_contract_due(2025,6),'choice','partial','payoutCents',20000,'waivedCents',10000));
 r:=public.trainer_contract_portal_request(owner_id,payload);if r->>'portalVersion'<>'2' then raise exception 'Authorized partial waiver failed: %',r;end if;
 r:=public.trainer_contract_portal_request(owner_id,jsonb_build_object('action','file','id',minor_cid,'kind','guardian_waiver_juni'));if r->>'hash'<>repeat('d',64) then raise exception 'Own guardian consent file unavailable';end if;
 update public.social_admins set is_blocked=true where user_id=owner_id;
 if public.trainer_contract_portal_request(owner_id,jsonb_build_object('action','get','id',cid))->>'status'<>'403' then raise exception 'Blocked owner read private documents';end if;
 if has_table_privilege('authenticated','private.trainer_contract_signatures','select') or has_function_privilege('anon','public.trainer_contract_portal_request(uuid,jsonb)','execute') then raise exception 'Private signatures exposed';end if;
end $test$;
rollback;
